class TaskBinding {static int integers(Integer[]a,int rule){alternate.Property<Integer>p=new alternate.Property<>(){public boolean test(Integer x){return switch(rule){case 0->x%2!=0;case 1->true;case 2->false;default->x<0;};}};return alternate.Counter.count(a,p);}static int strings(String[]a,int rule){alternate.Property<String>p=new alternate.Property<>(){public boolean test(String x){return switch(rule){case 0->x.length()>3;case 1->true;default->false;};}};return alternate.Counter.count(a,p);}}
